   [63]={next_id=64, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="少女和少年一同向上望去，神秘的光自山巅照耀着，如同面纱一般将整座冰山都笼罩其中。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="走吧。只要见到神明大人，就可以结束这场寒灾了。", msg_color="", msg_size=0, talker="桑斯", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="桑斯率先踏上了通往山顶的道路，涅普露紧随其后。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="冰山陡峭得近乎笔直，厚厚的积雪下隐藏着边界模糊的落脚处，形状完全不像是人工开凿而更像是自然风化的产物。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="风雪消弭，四周安静得只剩下两人的脚步声。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_1401.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
